const SLOT = {
  nila:  { src: "figurer/nila.webp",  img: null, ok: false },
  norin: { src: "figurer/norin.webp", img: null, ok: false }
};
function loadSlots(){
  for (const id of ["nila","norin"]) {
    const src = SPRITE_DATA[id] || SLOT[id].src;
    if (!src) continue;
    if (!SPRITE_DATA[id] && (!SLOT[id].src || SLOT[id]._tried)) continue;
    const im = new Image();
    im.onload = () => { if (im.width >= 14) { SLOT[id].img = im; SLOT[id].ok = true; } };
    im.onerror = () => { SLOT[id].ok = false; };
    SLOT[id]._tried = true;
    try { im.src = src; } catch (e) { SLOT[id].ok = false; }
  }
}
