let bgView=null;
function loadBG(k){
  if(!k || !BG_DATA[k] || BG_IMG[k] || BG_IMG["__l_"+k]) return;
  BG_IMG["__l_"+k]=true;
  const im=new Image();
  im.onload=()=>{ BG_IMG[k]=im; };
  im.onerror=()=>{};
  try{ im.src=BG_DATA[k]; }catch(e){}
}
function loadBackgrounds(){
  loadBG("karta");
}
function loadAtlas(){
  if(!ATLAS_DATA || !ATLAS_DATA.webp) return;
  ATLAS.frames = ATLAS_DATA.frames || {};
  const im=new Image();
  im.onload=()=>{ ATLAS.img=im; ATLAS.ok=true; };
  im.onerror=()=>{};
  try{ im.src=ATLAS_DATA.webp; }catch(e){}
}
function layoutBG(name){
  loadBG(name);
  const img=BG_IMG[name], meta=BG_META[name]||{fx:0.5,fy:0.5,fill:["#e8d7b8","#c9b892"],anchors:[]};
  if(!img||!img.width){
    bgView={dx:0,dy:0,dw:W,dh:H,scale:1,iw:1,ih:1,name};
    return null;
  }
  const iw=img.width, ih=img.height, anchors=meta.anchors||[];
  let scale=Math.max(W/iw, H/ih), dx, dy, dw, dh;
  if(anchors.length){
    let x0=1,y0=1,x1=0,y1=0;
    anchors.forEach(a=>{ x0=Math.min(x0,a.x); y0=Math.min(y0,a.y); x1=Math.max(x1,a.x); y1=Math.max(y1,a.y); });
    const pad=0.07;
    x0=Math.max(0,x0-pad); y0=Math.max(0,y0-pad); x1=Math.min(1,x1+pad); y1=Math.min(1,y1+pad);
    const need=Math.min(W/((x1-x0)*iw), H/((y1-y0)*ih));
    if(need<scale) scale=need;
    dw=iw*scale; dh=ih*scale;
    dx=W/2-((x0+x1)/2)*dw; dy=H/2-((y0+y1)/2)*dh;
  } else {
    dw=iw*scale; dh=ih*scale;
    dx=W/2-(meta.fx||0.5)*dw; dy=H/2-(meta.fy||0.5)*dh;
  }
  if(dw>=W) dx=clamp(dx, W-dw, 0); else dx=(W-dw)/2;
  if(dh>=H) dy=clamp(dy, H-dh, 0); else dy=(H-dh)/2;
  bgView={name,scale,dx,dy,dw,dh,iw,ih};
  return {img,meta};
}

let _ambiTiny=null;
let _paper=null;
function paperPattern(){
  if(_paper) return _paper;
  const c=document.createElement("canvas");
  c.width=128; c.height=128;
  const g=c.getContext("2d");
  const im=g.createImageData(128,128);
  for(let i=0;i<im.data.length;i+=4){
    const n=190+((Math.sin(i*12.9898)*43758.5453)%1)*50;
    im.data[i]=n; im.data[i+1]=n-10; im.data[i+2]=n-18; im.data[i+3]=48;
  }
  g.putImageData(im,0,0);
  _paper=c;
  return c;
}
let _paperPat=null;
function paperFill(){
  if(!_paperPat) _paperPat=ctx.createPattern(paperPattern(),"repeat");
  return _paperPat;
}
function fillPaper(c1,c2){
  const g=ctx.createLinearGradient(0,0,0,H);
  g.addColorStop(0,c1); g.addColorStop(1,c2||c1);
  ctx.fillStyle=g; ctx.fillRect(0,0,W,H);
  const pat=paperFill();
  if(!pat) return;
  ctx.save();
  ctx.globalAlpha=0.18;
  ctx.fillStyle=pat;
  ctx.fillRect(0,0,W,H);
  ctx.restore();
}
function figureH(kind, s){
  s=s||1;
  if(/baby$/.test(kind) || (kind&&kind.indexOf("baby")>=0)) return 64*s;
  if(kind==="butterfly"||kind==="ladybug") return 70*s;
  return 88*s;
}
function drawAmbilight(img){
  if(!img||!img.width) return;
  if(!_ambiTiny) _ambiTiny=document.createElement("canvas");
  const aw=96, ah=Math.max(1, Math.round(96*img.height/img.width));
  if(_ambiTiny.width!==aw || _ambiTiny.height!==ah){ _ambiTiny.width=aw; _ambiTiny.height=ah; }
  const a=_ambiTiny.getContext("2d");
  a.clearRect(0,0,aw,ah);
  a.drawImage(img,0,0,aw,ah);
  const sc=Math.max(W/aw, H/ah)*1.28;
  const dw=aw*sc, dh=ah*sc;
  ctx.save();
  ctx.imageSmoothingEnabled=true;
  ctx.imageSmoothingQuality="high";
  ctx.drawImage(_ambiTiny, (W-dw)/2, (H-dh)/2, dw, dh);
  ctx.fillStyle="rgba(10,8,18,0.34)";
  ctx.fillRect(0,0,W,H);
  ctx.restore();
}
function drawWorldVignette(dx,dy,dw,dh){
  const v=Math.max(18, Math.min(56, Math.min(dw,dh)*0.07));
  if(dy>0.5){
    const g=ctx.createLinearGradient(0, Math.max(0,dy-v*0.2), 0, dy+v);
    g.addColorStop(0,"rgba(0,0,0,0)");
    g.addColorStop(0.28,"rgba(0,0,0,0.28)");
    g.addColorStop(1,"rgba(0,0,0,0)");
    ctx.fillStyle=g; ctx.fillRect(0, Math.max(0,dy-v*0.2), W, v*1.2);
  }
  if(dy+dh<H-0.5){
    const g=ctx.createLinearGradient(0, dy+dh-v, 0, dy+dh+v*0.2);
    g.addColorStop(0,"rgba(0,0,0,0)");
    g.addColorStop(0.72,"rgba(0,0,0,0.28)");
    g.addColorStop(1,"rgba(0,0,0,0)");
    ctx.fillStyle=g; ctx.fillRect(0, dy+dh-v, W, v+v*0.2);
  }
  if(dx>0.5){
    const g=ctx.createLinearGradient(Math.max(0,dx-v*0.2), 0, dx+v, 0);
    g.addColorStop(0,"rgba(0,0,0,0)");
    g.addColorStop(0.28,"rgba(0,0,0,0.28)");
    g.addColorStop(1,"rgba(0,0,0,0)");
    ctx.fillStyle=g; ctx.fillRect(Math.max(0,dx-v*0.2), 0, v*1.2, H);
  }
  if(dx+dw<W-0.5){
    const g=ctx.createLinearGradient(dx+dw-v, 0, dx+dw+v*0.2, 0);
    g.addColorStop(0,"rgba(0,0,0,0)");
    g.addColorStop(0.72,"rgba(0,0,0,0.28)");
    g.addColorStop(1,"rgba(0,0,0,0)");
    ctx.fillStyle=g; ctx.fillRect(dx+dw-v, 0, v+v*0.2, H);
  }
}
function hintBubble(ax, ay, kind, s, icon){
  const fh=figureH(kind,s);
  const bw=36, bh=32, gap=10, r=8;
  const L=lay();
  const hudSafe=L.pad + Math.max(64, 56*L.s) + 6;
  let bx=ax-bw/2, by=ay-fh-gap-bh, tail="down";
  if(by<hudSafe){
    const headY=ay-fh*0.72;
    by=headY-bh/2;
    if(ax+28+bw < W-6){ bx=ax+28; tail="left"; }
    else { bx=ax-28-bw; tail="right"; }
  }
  bx=clamp(bx, 6, W-bw-6);
  by=clamp(by, hudSafe, H-bh-6);
  ctx.fillStyle="#fff6ea";
  ctx.strokeStyle="#e8c56b";
  ctx.lineWidth=2;
  rr(bx,by,bw,bh,r); ctx.fill(); ctx.stroke();
  ctx.beginPath();
  if(tail==="down"){
    const tx=clamp(ax, bx+8, bx+bw-8);
    ctx.moveTo(tx-6, by+bh-1); ctx.lineTo(tx, ay-fh-2); ctx.lineTo(tx+6, by+bh-1);
  } else if(tail==="left"){
    const ty=clamp(ay-fh*0.7, by+6, by+bh-6);
    ctx.moveTo(bx+1, ty-5); ctx.lineTo(ax+10, ay-fh*0.65); ctx.lineTo(bx+1, ty+5);
  } else {
    const ty=clamp(ay-fh*0.7, by+6, by+bh-6);
    ctx.moveTo(bx+bw-1, ty-5); ctx.lineTo(ax-10, ay-fh*0.65); ctx.lineTo(bx+bw-1, ty+5);
  }
  ctx.closePath(); ctx.fill();
  blit(icon, bx+bw/2, by+bh-5, {h:20});
  return {x:bx,y:by,w:bw,h:bh};
}
function drawHeart(x,y){
  ctx.fillStyle="#f37a62";
  ctx.beginPath(); ctx.moveTo(x,y); ctx.bezierCurveTo(x-12,y-12,x-14,y+6,x,y+12); ctx.bezierCurveTo(x+14,y+6,x+12,y-12,x,y); ctx.fill();
}

const _bgCache={ name:"", w:0, h:0, canvas:null };
function drawBG(name, fallback){
  const laid=layoutBG(name);
  const v=bgView;
  const letterboxed=laid && v && (v.dw < W-1 || v.dh < H-1);
  const fill=(BG_META[name]||{}).fill||["#e8d7b8","#c9b892"];
  if(_bgCache.canvas && _bgCache.name===name && _bgCache.w===W && _bgCache.h===H && laid){
    ctx.drawImage(_bgCache.canvas, 0, 0, W, H);
    return true;
  }
  /* G5: ingen suddig ambilight. Pappersvätt + korn fyller letterbox. */
  fillPaper(fill[0], fill[1]||fill[0]);
  if(!laid){ if(fallback) fallback(); return false; }
  ctx.drawImage(laid.img, v.dx, v.dy, v.dw, v.dh);
  if(letterboxed) drawWorldVignette(v.dx, v.dy, v.dw, v.dh);
  if(!_bgCache.canvas) _bgCache.canvas=document.createElement("canvas");
  _bgCache.canvas.width=Math.max(1,W);
  _bgCache.canvas.height=Math.max(1,H);
  _bgCache.canvas.getContext("2d").drawImage(cv, 0, 0, cv.width, cv.height, 0, 0, W, H);
  _bgCache.name=name; _bgCache.w=W; _bgCache.h=H;
  return true;
}

function drawSkyParallax(cam, worldW){
  const img=BG_IMG.himmel;
  const g=ctx.createLinearGradient(0,0,0,H);
  g.addColorStop(0,"#cfe6f6"); g.addColorStop(1,"#f3e0d0");
  ctx.fillStyle=g; ctx.fillRect(0,0,W,H);
  if(!img||!img.width){ bgSky(); return; }
  const t=clamp(cam/Math.max(400,(worldW||8000)-700),0,1);
  const sc=Math.max(H/img.height, W/img.width);
  const dw=img.width*sc, dh=img.height*sc;
  ctx.drawImage(img, -t*Math.max(0,dw-W), (H-dh)/2, dw, dh);
}
function worldToX(nx){ return (bgView?bgView.dx:0)+nx*(bgView?bgView.dw:W); }
function worldToY(ny){ return (bgView?bgView.dy:0)+ny*(bgView?bgView.dh:H); }
function screenToWorld(x,y){
  if(!bgView) return {x:x/W,y:y/H};
  return {x:(x-bgView.dx)/bgView.dw, y:(y-bgView.dy)/bgView.dh};
}
function spr(name){ return ATLAS.ok && ATLAS.frames && ATLAS.frames[name]; }
function blit(name, x, y, opt){
  opt=opt||{};
  const f=spr(name); if(!f||!ATLAS.img) return false;
  const th=(opt.h||110)*(opt.scale||1);
  const sc=th/f.h, dw=f.w*sc, dh=f.h*sc;
  ctx.save();
  ctx.translate(x,y);
  if(opt.rot) ctx.rotate(opt.rot);
  ctx.scale(opt.face||1, 1);
  ctx.scale(opt.sx||1, opt.sy||1);
  const bob=opt.bob||0;
  if(opt.anchor==="center") ctx.drawImage(ATLAS.img,f.x,f.y,f.w,f.h,-dw/2,-dh/2,dw,dh);
  else ctx.drawImage(ATLAS.img,f.x,f.y,f.w,f.h,-dw/2,-dh+bob,dw,dh);
  ctx.restore();
  return true;
}

