  drawHero(W*0.62, H*0.78, {who:"norin", expr:d2.expr, scale:L.s*1.25, face:-1, pose:d2.pose, sx:d2.sx, sy:d2.sy, bob:d2.bob, rot:d2.rot, dx:d2.dx});
