/* ---- FÖRÄLDRAÖVERSIKT ---- */
function updForalder(){
  const id=hitId();
  if(id==="btn-tal"){ tala("oversikt"); return; }
  if(id==="btn-map" || id==="btn-stang" || (id && id!=="bg" && sceneT>0.3 && id==="tap-next")){
    /* handled below */
  }
  if(handleHud(id)) return;
  if(id==="btn-stang" || id==="btn-map"){ sfx("tap"); go("map"); return; }
  if(id==="btn-stickers"||id==="btn-stickers-bar"){ sfx("open"); go("stickers"); return; }
}
function drawForalder(){
  fillPaper("#f7e8d0", "#e8d4b0");
  const L=lay();
  const x=Math.max(24, W*0.08), y=L.top+16, w=W-x*2, h=H-y-L.pad-8;
  ctx.fillStyle="rgba(255,247,230,0.96)";
  rr(x,y,w,h,18); ctx.fill();
  ctx.strokeStyle="#e8c56b"; ctx.lineWidth=3; ctx.stroke();
  ctx.fillStyle="#5a3e3a";
  ctx.textAlign="left"; ctx.textBaseline="top";
  ctx.font="700 "+Math.floor(22*L.s)+"px Trebuchet MS,Nunito,sans-serif";
  ctx.fillText("Översikt för vuxna", x+72, y+18);
  drawEar(x+w-36, y+32, 1.15);
  addHit("btn-tal", x+w-64, y+8, 56, 56);
  const hero=persist.hero?PAL[persist.hero].name:"ingen vald än";
  const n=minnenAntal();
  const lines=[
    "Spelar: "+hero+". Minnen i boken: "+n+" av 5."+(persist.ended?" Boken är full och festen är nådd.":""),
    "Röd tråd: hjälp djuren, odla till festen, plocka stjärnor, hitta en skatt och baka tårtan.",
    "Barn som inte läser styr med bilder och stora knappar. Örat läser upp korta meningar.",
    "Uppläsningen är talsyntes, inte en inspelad barnröst (EJ VERIFIERAT).",
    "Inga straff, alla världar är öppna. Sparningen sköts av Spara, Fortsätt och Nytt i listen."
  ];
  ctx.font="500 "+Math.floor(14*L.s)+"px Trebuchet MS,Nunito,sans-serif";
  let ty=y+58;
  lines.forEach(line=>{
    const words=line.split(" ");
    let row="";
    const maxW=w-48;
    words.forEach(word=>{
      const trial=row?row+" "+word:word;
      if(ctx.measureText(trial).width>maxW){ ctx.fillText(row, x+24, ty); ty+=20*L.s; row=word; }
      else row=trial;
    });
    if(row){ ctx.fillText(row, x+24, ty); ty+=28*L.s; }
  });
  /* ikonrad för de fem minnena */
  TRAD.forEach((tr,i)=>{
    const sx=x+40+i*((w-80)/4), sy=Math.min(y+h-90, ty+20);
    const on=!!persist.stickers[tr.id];
    drawStickerIcon(WORLDS.find(w=>w.id===tr.id).sticker, sx, sy, 2.2, on);
    addHit("sticker-"+tr.id, sx-28, sy-28, 56, 56);
  });
  ctx.fillStyle="#ffe27a";
  rr(x+w-150, y+h-52, 130, 36, 14); ctx.fill();
  ctx.strokeStyle="#e8c56b"; ctx.stroke();
  ctx.fillStyle="#5a3e3a"; ctx.textAlign="center"; ctx.textBaseline="middle";
  ctx.font="700 15px Trebuchet MS,Nunito,sans-serif";
  ctx.fillText("Till kartan", x+w-85, y+h-34);
  addHit("btn-stang", x+w-150, y+h-52, 130, 36);
}

/* ---- SPARKOD (inga formulär, bara bokstavsknappar) ---- */
function initKod(){ G={ letters:"", flash:"" }; }
function updKod(){
  if(!G.letters) G.letters="";
  const id=hitId();
  if(!id) return;
  if(handleHud(id)) return;
  if(id==="kod-ok"){
    if(G.letters===SPARKOD){ sfx("cheer"); G.flash="ok"; setTimeout(()=>go("map"), 600); }
    else { sfx("softno"); G.letters=""; G.flash="no"; }
    return;
  }
  if(id==="kod-del"){ G.letters=G.letters.slice(0,-1); sfx("tap"); return; }
  if(id.startsWith("k-")){
    const ch=id.slice(2);
    if(G.letters.length<4){ G.letters+=ch; sfx("tap"); }
  }
}
function drawKod(){
  sky("#f7e0c0","#cfe6f8");
  const L=lay();
  ctx.fillStyle="#5a3e3a";
  ctx.font="700 "+Math.floor(28*L.s)+"px Trebuchet MS,Nunito,sans-serif";
  ctx.textAlign="center"; ctx.fillText("NINO", W/2, H*0.16);
  // four slots
  const s=Math.max(64, 56*L.s);
  for(let i=0;i<4;i++){
    const x=W/2-(s*2+18)+i*(s+12);
    ctx.fillStyle="#fff6ea"; rr(x, H*0.22, s, s, 12); ctx.fill();
    ctx.strokeStyle="#e8c56b"; ctx.lineWidth=3; ctx.stroke();
    ctx.fillStyle="#5a3e3a";
    ctx.font="700 "+Math.floor(s*0.5)+"px Trebuchet MS,sans-serif";
    ctx.textBaseline="middle";
    ctx.fillText((G.letters||"")[i]||"", x+s/2, H*0.22+s/2);
  }
  const keys=["N","I","O","A","B","C","D","E"];
  keys.forEach((ch,i)=>{
    const col=i%4, row=Math.floor(i/4);
    const x=W/2-(s*2+18)+col*(s+12);
    const y=H*0.42+row*(s+12);
    ctx.fillStyle="#fff6ea"; rr(x,y,s,s,12); ctx.fill();
    ctx.strokeStyle="#c8b07a"; ctx.lineWidth=2; ctx.stroke();
    ctx.fillStyle="#5a3e3a";
    ctx.font="700 "+Math.floor(s*0.4)+"px Trebuchet MS,sans-serif";
    ctx.textBaseline="middle"; ctx.fillText(ch, x+s/2, y+s/2);
    addHit("k-"+ch, x,y,s,s);
  });
  const yb=H*0.42+2*(s+12);
  ctx.fillStyle="#f37a62"; rr(W/2-s*2-18, yb, s*1.5, s, 12); ctx.fill();
  ctx.fillStyle="#fff"; ctx.font="700 20px Trebuchet MS,sans-serif"; ctx.fillText("⌫", W/2-s*2-18+s*0.75, yb+s/2);
  addHit("kod-del", W/2-s*2-18, yb, s*1.5, s);
  ctx.fillStyle="#2fb3a8"; rr(W/2+s*0.5, yb, s*1.8, s, 12); ctx.fill();
  ctx.fillStyle="#fff"; ctx.fillText("★", W/2+s*0.5+s*0.9, yb+s/2);
  addHit("kod-ok", W/2+s*0.5, yb, s*1.8, s);
  drawHud(true);
}

/* ======== VÄRLD 1: Djurräddningen ======== */
function initRescue(){
  layoutBG("skog");
  const p=lead();
  p.x=0.55; p.y=0.86; p.vx=0; p.pose="idle"; p.phase=0; p.expr="glad"; p.face=1; p.carry=null; p.goal=null;
  G = {
    animals: [
      { id:"owl",   kind:"owl-baby", parent:"owl",   col:"#d8c09a", baby:{x:0.45,y:0.80, hid:false}, parentP:{x:0.805,y:0.22}, home:false, tracks:null, hideX:0.45, hideY:0.80 },
      { id:"bunny", kind:"bunny-baby", parent:"bunny", col:"#f2e6d8", baby:{x:0.64,y:0.72, hid:true, bush:true}, parentP:{x:0.823,y:0.62}, home:false, tracks:[{x:0.76,y:0.70},{x:0.71,y:0.72},{x:0.67,y:0.73}], hideX:0.64, hideY:0.72 },
      { id:"fox",   kind:"fox-baby", parent:"fox",   col:"#e8893a", baby:{x:0.36,y:0.78, hid:true, flower:true}, parentP:{x:0.187,y:0.61}, home:false, tracks:null, sound:true, hideX:0.36, hideY:0.78 },
      { id:"hedge", kind:"hedge-baby", parent:"hedge", col:"#8a6238", baby:{x:0.50,y:0.90, hid:true, log:true}, parentP:{x:0.13,y:0.84}, home:false, tracks:[{x:0.40,y:0.88},{x:0.32,y:0.86},{x:0.22,y:0.85}], hideX:0.50, hideY:0.90 }
    ],
    bushOpen:false, logOpen:false, flowerGlow:false, revealedFox:false
  };
}


function walkToward(p, gx, gy, speed){
  const px=worldToX(p.x), py=worldToY(p.y);
  const dx=gx-px, dy=gy-py;
  const dist=Math.hypot(dx,dy);
  const max=speed||180;
  if(dist<12){
    p.vx *= Math.pow(0.02, DT);
    if(Math.abs(p.vx)<8){ p.vx=0; p.pose = p.carry?"carry":"idle"; p.goal=null; }
    return true;
  }
  const dir=Math.sign(dx)||1;
  p.face=dir;
  const acc=700;
  p.vx = (p.vx||0) + dir*acc*DT;
  p.vx = clamp(p.vx, -max, max);
  const step=p.vx*DT;
  if(Math.abs(step)>Math.abs(dx)) p.vx=dx/Math.max(DT,1/120);
  const dw=bgView?bgView.dw:W, dh=bgView?bgView.dh:H;
  p.x += (p.vx*DT)/dw;
  if(Math.abs(dy)>8) p.y += (dy*2.5*DT)/dh;
  p.pose = p.carry?"carry":"walk";
  const stridePx=56;
  p.phase = (p.phase||0) + Math.abs(p.vx)*DT/stridePx;
  if(p.phase>1) p.phase-=1;
  const cyc=p.phase;
  if(!p._lastC) p._lastC=0;
  if((p._lastC<0.5 && cyc>=0.5) || (p._lastC>0.8 && cyc<0.2)){ if(T>stepGate){ sfx("step"); stepGate=T+0.12; } }
  p._lastC=cyc;
  return false;
}


function updRescue(){
  layoutBG("skog");
  const p=lead();
  const id=hitId();
  if(handleHud(id)) return;
  if(id && id!=="bg" && !id.startsWith("btn-")){
    if(id==="bush"){ G.bushOpen=true; sfx("pop"); burst(tap.x,tap.y,8,"#7cba72"); G.animals[1].baby.hid=false; return; }
    if(id==="log"){ G.logOpen=true; sfx("pop"); G.animals[3].baby.hid=false; return; }
    if(id==="foxflower" || id==="parent-fox"){
      G.flowerGlow=true;
      if(id==="foxflower"){ G.revealedFox=true; G.animals[2].baby.hid=false; sfx("heart"); }
      if(id==="parent-fox"){ sfx("heart"); }
    }
    if(id.startsWith("baby-")){
      const a=G.animals.find(a=>a.id===id.slice(5));
      if(a && !a.home && !a.baby.hid){
        p.carry=a.id; p.expr="modig"; p.pose="carry";
        sfx("ok"); burst(worldToX(a.baby.x), worldToY(a.baby.y), 8, a.col);
      }
      return;
    }
    if(id.startsWith("parent-")){
      const kind=id.slice(7);
      const a=G.animals.find(a=>a.id===kind);
      if(a && p.carry===a.id){
        a.home=true; p.carry=null; p.expr="skratt"; p.pose="cheer";
        sfx("heart"); confetti(worldToX(a.parentP.x), worldToY(a.parentP.y)-20, 18);
        G.winCheer=0.7;
        if(G.animals.every(a=>a.home)) G.winIn=0.8;
        return;
      } else if(p.carry && a && p.carry!==a.id){
        sfx("softno"); a._shake=0.4; p.expr="fundersam";
        return;
      } else if(a && !a.home){
        p.goal={x:a.parentP.x, y:Math.min(0.95, a.parentP.y+0.15)};
        if(a.sound){ sfx("heart"); G.flowerGlow=true; }
      }
    }
  } else if(id==="bg" && tap){
    const w=screenToWorld(tap.x,tap.y);
    p.goal={x:clamp(w.x,0.08,0.92), y:clamp(w.y,0.58,0.96)};
  }
  if(p.goal) walkToward(p, worldToX(p.goal.x), worldToY(p.goal.y));
  else if(!p.carry) { p.pose = p.pose==="cheer"?p.pose:"idle"; p.vx=0; }
  if(G.winCheer){ G.winCheer-=DT; if(G.winCheer<=0 && p.pose==="cheer"&&!p.carry){ p.pose="idle"; p.expr="glad"; } }
  if(p.carry){
    const a=G.animals.find(a=>a.id===p.carry);
    if(a){ a.baby.x=lerp(a.baby.x, p.x + p.face*0.06, 0.2); a.baby.y=lerp(a.baby.y, p.y-0.02, 0.2); }
  }
  G.animals.forEach(a=>{ if(a._shake) a._shake=Math.max(0,a._shake-DT); });
}

function drawRescue(){
  drawBG("skog", bgForest);
  const L=lay();
  const bx=worldToX(0.64), by=worldToY(0.70);
  if(!G.bushOpen){
    ctx.strokeStyle="rgba(255,247,200,0.0)";
    addHit("bush", bx-40, by-40, 80, 80);
    if(idle>2) sparkle(bx, by-16);
  }
  const lx=worldToX(0.50), ly=worldToY(0.90);
  if(!G.logOpen){ addHit("log", lx-40, ly-36, 80, 72); if(idle>2) sparkle(lx, ly-16); }
  const fx=worldToX(0.36), fy=worldToY(0.76);
  if(G.flowerGlow){ ctx.globalAlpha=0.3; ctx.fillStyle="#ffb060"; disk(fx,fy,24); ctx.fill(); ctx.globalAlpha=1; }
  addHit("foxflower", fx-32, fy-32, 70, 70);
  G.animals.forEach(a=>{
    if(a.tracks && !a.home && a.baby.hid){
      a.tracks.forEach(t=>{ ctx.globalAlpha=0.75; blit("seed", worldToX(t.x), worldToY(t.y), {h:14}); ctx.globalAlpha=1; });
    }
  });
  G.animals.forEach(a=>{
    const px=worldToX(a.parentP.x), py=worldToY(a.parentP.y);
    const shake=a._shake?Math.sin(T*20)*4:0;
    drawAnimal(a.parent, px+shake, py, L.s, a.home?"skratt":"fundersam", 1);
    let hitX=px-36, hitY=py-figureH(a.parent,L.s)-8, hitW=72, hitH=figureH(a.parent,L.s)+16;
    if(!a.home){
      const bub=hintBubble(px, py, a.parent, L.s, a.kind);
      hitX=Math.min(hitX,bub.x-4); hitY=Math.min(hitY,bub.y-4);
      hitW=Math.max(px+36,bub.x+bub.w+4)-hitX; hitH=Math.max(py+8,bub.y+bub.h+4)-hitY;
    } else {
      drawHeart(px, py-figureH(a.parent,L.s)-6);
    }
    addHit("parent-"+a.id, hitX, hitY, hitW, hitH);
    if(!a.home && !a.baby.hid){
      const bx=worldToX(a.baby.x), by=worldToY(a.baby.y);
      drawAnimal(a.kind, bx, by, L.s*0.85, "glad", 1);
      addHit("baby-"+a.id, bx-36, by-50, 72, 80);
    }
  });
  const p=lead();
  drawHero(worldToX(p.x), worldToY(p.y), {who:p.id, expr:p.expr, scale:L.s*1.05, face:p.face, pose:p.pose, phase:p.phase});
  if(p.carry){
    const a=G.animals.find(a=>a.id===p.carry);
    if(a) drawAnimal(a.kind, worldToX(p.x)+p.face*22, worldToY(p.y)-70, 0.7, "glad", p.face);
  }
  if(idle>4){
    const next=G.animals.find(a=>!a.home);
    if(next){
      const tx = next.baby.hid ? worldToX(next.hideX) : (p.carry===next.id?worldToX(next.parentP.x):worldToX(next.baby.x));
      const ty = next.baby.hid ? worldToY(next.hideY) : (p.carry===next.id?worldToY(next.parentP.y):worldToY(next.baby.y));
      sparkle(tx, ty-24);
    }
  }
  drawHud(true);
}


/* ======== VÄRLD 2: Trädgårdsmagin ======== */
const SEEDS = [
  { id:"red",    col:"#f37a62", shape:"circle" },
  { id:"yellow", col:"#ffe27a", shape:"star" },
  { id:"blue",   col:"#7ec8f0", shape:"drop" },
  { id:"purple", col:"#c9a0e8", shape:"heart" }
];
function initGarden(){
  layoutBG("tradgard");
  persist.gardenVisit = (persist.gardenVisit||0)+1; saveNow();
  const p=lead(); p.x=0.36; p.y=0.92; p.vx=0; p.pose="idle"; p.expr="glad"; p.goal=null; p.phase=0;
  G = {
    plots: [
      { i:0, seed:null, stage:0, grow:0, watering:0, x:0.22, y:0.60, rx:0.13, ry:0.09, paintedBloom:true },
      { i:1, seed:null, stage:0, grow:0, watering:0, x:0.495, y:0.505, rx:0.11, ry:0.08 },
      { i:2, seed:null, stage:0, grow:0, watering:0, x:0.445, y:0.70, rx:0.13, ry:0.09 },
      { i:3, seed:null, stage:0, grow:0, watering:0, x:0.728, y:0.636, rx:0.142, ry:0.132 }
    ],
    tool:null, canHasWater:true, visit:persist.gardenVisit, done:false, wanted:"yellow"
  };
}

function updGarden(){
  layoutBG("tradgard");
  const p=lead();
  const id=hitId();
  if(handleHud(id)) return;
  if(id && id.startsWith("seed-")){ G.tool=id.slice(5); sfx("tap"); }
  if(id==="can"){ G.tool="can"; sfx("water"); }
  if(id && id.startsWith("plot-")){
    const i=+id.slice(5);
    const pl=G.plots[i];
    if(G.tool && G.tool!=="can" && pl.stage===0){
      pl.seed=G.tool; pl.stage=1; pl.grow=0; sfx("plant");
      p.pose="plant"; setTimeout(()=>{ if(p.pose==="plant") p.pose="idle"; }, 400);
    } else if(G.tool==="can" && pl.stage>0 && pl.stage<3 && pl.grow<=0){
      pl.watering=0.35; pl.grow=1.1; sfx("water");
      p.pose="plant"; setTimeout(()=>{ if(p.pose==="plant") p.pose="idle"; }, 400);
    }
  }
  if(id==="bg" && tap){ const w=screenToWorld(tap.x,tap.y); p.goal={x:clamp(w.x,0.1,0.9), y:clamp(w.y,0.7,0.95)}; }
  if(p.goal) walkToward(p, worldToX(p.goal.x), worldToY(p.goal.y), 160);
  G.plots.forEach(pl=>{
    if(pl.grow>0){
      pl.grow-=DT; if(pl.watering>0) pl.watering-=DT;
      if(pl.grow<=0 && pl.stage<3){ pl.stage++; sfx("pop"); pl.just=true; }
    }
  });
  const bloomed=G.plots.filter(p=>p.stage>=3);
  const hasWanted=bloomed.some(p=>p.seed===G.wanted);
  if(!G.done && bloomed.length>=3 && hasWanted){ G.done=true; persist.gardenBloomed=true; saveNow(); G.winIn=0.9; }
}

const _soilCache=new Map();
function drawSoil(x,y,rx,ry,seed){
  // Målad jord — cachad, så 56 ellipser inte ritas om varje ram.
  const key=seed+"|"+Math.round(rx)+"x"+Math.round(ry);
  let c=_soilCache.get(key);
  if(!c){
    const pad=3;
    c=document.createElement("canvas");
    c.width=Math.max(2, Math.ceil(rx*2+pad*2));
    c.height=Math.max(2, Math.ceil(ry*2+pad*2));
    const g=c.getContext("2d");
    g.translate(c.width/2, c.height/2);
    g.scale(rx, ry);
    let s = ((seed + 1) * 7477 + 13) >>> 0;
    const rnd = () => { s = (Math.imul(s, 16807) + 0) >>> 0; return (s % 10000) / 10000; };
    const grad = g.createRadialGradient(-0.22, -0.32, 0.08, 0.05, 0.1, 1.05);
    grad.addColorStop(0, "#7a5630");
    grad.addColorStop(0.28, "#6a4a28");
    grad.addColorStop(0.55, "#553e21");
    grad.addColorStop(0.82, "#4a351c");
    grad.addColorStop(1, "#3f2c16");
    g.fillStyle = grad;
    g.beginPath(); g.arc(0, 0, 1, 0, TAU); g.fill();
    g.save();
    g.beginPath(); g.arc(0, 0, 1, 0, TAU); g.clip();
    for(let i=0;i<34;i++){
      const a = rnd()*TAU, r = Math.sqrt(rnd())*0.84;
      const cx = Math.cos(a)*r, cy = Math.sin(a)*r*0.92;
      const rw = 0.07 + rnd()*0.14, rh = rw*(0.5 + rnd()*0.45);
      const lite = rnd();
      g.fillStyle = lite > 0.62 ? "rgba(116,88,48,0.42)" : lite > 0.3 ? "rgba(58,38,16,0.38)" : "rgba(90,64,32,0.32)";
      g.beginPath(); g.ellipse(cx, cy, rw, rh, rnd()*TAU, 0, TAU); g.fill();
    }
    for(let i=0;i<22;i++){
      const a = rnd()*TAU, r = Math.sqrt(rnd())*0.78;
      g.fillStyle = rnd() > 0.5 ? "rgba(130,96,54,0.55)" : "rgba(40,26,12,0.45)";
      g.beginPath(); g.arc(Math.cos(a)*r, Math.sin(a)*r*0.92, 0.02+rnd()*0.035, 0, TAU); g.fill();
    }
    g.restore();
    const rim = g.createRadialGradient(0, 0, 0.72, 0, 0, 1);
    rim.addColorStop(0, "rgba(0,0,0,0)");
    rim.addColorStop(0.7, "rgba(40,26,12,0.08)");
    rim.addColorStop(1, "rgba(30,18,8,0.28)");
    g.fillStyle = rim;
    g.beginPath(); g.arc(0, 0, 1, 0, TAU); g.fill();
    if(_soilCache.size>24) _soilCache.clear();
    _soilCache.set(key,c);
  }
  ctx.drawImage(c, x-c.width/2, y-c.height/2);
}
function drawGarden(){
  drawBG("tradgard", bgGarden);
  const L=lay();
  const p=lead();
  G.plots.forEach(pl=>{
    const x=worldToX(pl.x), y=worldToY(pl.y);
    const rx=pl.rx*(bgView?bgView.dw:W), ry=pl.ry*(bgView?bgView.dh:H);
    if(pl.stage===0 || (pl.paintedBloom && pl.stage<3)){
      drawSoil(x, y, rx*0.95, ry*0.88, pl.i);
    }
    if(pl.stage===1 && !pl.paintedBloom) blit("seed", x, y, {h:Math.max(22, ry*0.7)});
    if(pl.stage===2) blit("sprout", x, y, {h:Math.max(36, ry*1.1)});
    if(pl.stage>=3){
      if(pl.seed==="yellow") blit("sunflower", x, y+4, {h:Math.max(44, ry*1.4)});
      else if(pl.seed==="red"||pl.paintedBloom) blit("bud", x, y+4, {h:Math.max(40, ry*1.3)});
      else blit("sunflower", x, y+4, {h:Math.max(44, ry*1.4)});
    }
    if(pl.just){ burst(x,y-20,10,"#8fd08a"); pl.just=false; }
    if(pl.watering>0){
      ctx.strokeStyle="rgba(120,180,230,0.7)"; ctx.lineWidth=2;
      for(let i=0;i<5;i++){ ctx.beginPath(); ctx.moveTo(x-10+i*5, y-50); ctx.lineTo(x-8+i*5, y-20); ctx.stroke(); }
    }
    addHit("plot-"+pl.i, x-Math.max(32,rx), y-Math.max(32,ry*1.4), Math.max(64,rx*2), Math.max(64,ry*2.2));
  });
  const seeds=[{id:"red",x:0.54,y:0.92,col:"#f37a62"},{id:"yellow",x:0.68,y:0.92,col:"#ffe27a"},{id:"blue",x:0.82,y:0.92,col:"#7ec8f0"},{id:"purple",x:0.94,y:0.92,col:"#c9a0e8"}];
  seeds.forEach(sd=>{
    const x=worldToX(sd.x), y=worldToY(sd.y);
    const sel=G.tool===sd.id;
    ctx.fillStyle=sel?"#ffe27a":"rgba(255,247,230,0.0)";
    if(sel){ disk(x,y-6,28); ctx.fill(); }
    blit("seed", x, y, {h:34});
    ctx.strokeStyle=sd.col; ctx.lineWidth=3; disk(x,y-8,20); ctx.stroke();
    addHit("seed-"+sd.id, x-32, y-40, 64, 64);
  });
  const cx=worldToX(0.88), cy=worldToY(0.66);
  if(G.tool==="can"){ ctx.fillStyle="rgba(255,226,122,0.45)"; disk(cx,cy,36); ctx.fill(); }
  addHit("can", cx-36, cy-36, 72, 72);
  const bx=worldToX(0.62), by=worldToY(0.38);
  drawAnimal("butterfly", bx, by, L.s, "glad", 1);
  ctx.fillStyle="#fff6ea"; rr(bx+18, by-48, 54, 40, 10); ctx.fill();
  ctx.strokeStyle="#e8c56b"; ctx.lineWidth=2; ctx.stroke();
  blit("sunflower", bx+45, by-12, {h:32});
  drawHero(worldToX(p.x), worldToY(p.y), {who:p.id, expr:p.expr, scale:L.s, face:p.face||1, pose:p.pose, phase:p.phase});
  if(idle>4){
    const empty=G.plots.find(pl=>pl.stage===0);
    const thirsty=G.plots.find(pl=>pl.stage>0&&pl.stage<3&&pl.grow<=0);
    if(empty && !G.tool) sparkle(worldToX(0.68), worldToY(0.92));
    else if(empty && G.tool && G.tool!=="can") sparkle(worldToX(empty.x), worldToY(empty.y));
    else if(thirsty) sparkle(cx,cy);
  }
  drawHud(true);
}


/* ======== VÄRLD 3: Molnäventyret ======== */
function initClouds(){
  layoutBG("himmel");
  const p=lead();
  G = {
    plats:[{x:40,y:400,w:380,h:40,typ:"ground"},{x:420,y:388,w:250,h:34,typ:"cloud"},{x:718,y:371,w:242,h:34,typ:"cloud"},{x:1013,y:357,w:234,h:34,typ:"cloud"},{x:1305,y:349,w:226,h:34,typ:"cloud"},{x:1594,y:347,w:218,h:34,typ:"cloud"},{x:1880,y:350,w:250,h:34,typ:"cloud"},{x:2203,y:355,w:242,h:34,typ:"cloud"},{x:2493,y:400,w:234,h:34,typ:"cloud",move:14},{x:2780,y:400,w:226,h:34,typ:"cloud"},{x:3064,y:397,w:218,h:34,typ:"cloud"},{x:3345,y:385,w:250,h:34,typ:"cloud"},{x:3663,y:369,w:242,h:34,typ:"cloud"},{x:3978,y:352,w:234,h:34,typ:"cloud"},{x:4260,y:336,w:226,h:34,typ:"cloud"},{x:4539,y:367,w:218,h:34,typ:"cloud"},{x:4815,y:362,w:250,h:34,typ:"cloud"},{x:5128,y:364,w:242,h:34,typ:"cloud",move:14},{x:5438,y:369,w:234,h:34,typ:"cloud"},{x:5745,y:374,w:226,h:34,typ:"cloud"},{x:6019,y:376,w:218,h:34,typ:"cloud"},{x:6290,y:373,w:250,h:34,typ:"cloud"},{x:6598,y:400,w:242,h:34,typ:"cloud"},{x:6903,y:391,w:234,h:34,typ:"cloud"},{x:7205,y:375,w:226,h:34,typ:"cloud"},{x:7504,y:357,w:218,h:34,typ:"cloud"},{x:7770,y:344,w:250,h:34,typ:"cloud",move:14},{x:8073,y:337,w:242,h:34,typ:"cloud"},{x:8373,y:336,w:234,h:34,typ:"cloud"},{x:8670,y:382,w:226,h:34,typ:"cloud"},{x:8964,y:387,w:218,h:34,typ:"cloud"},{x:9255,y:391,w:250,h:34,typ:"cloud"},{x:9553,y:391,w:242,h:34,typ:"cloud"},{x:9848,y:384,w:234,h:34,typ:"cloud"},{x:10140,y:372,w:226,h:34,typ:"cloud"},{x:10429,y:355,w:218,h:34,typ:"cloud",move:14},{x:10715,y:380,w:250,h:34,typ:"cloud"},{x:11038,y:365,w:242,h:34,typ:"cloud"},{x:11328,y:355,w:234,h:34,typ:"cloud"},{x:11655,y:328,w:450,h:44,typ:"goal"}],
    stars:[{x:827,y:321,got:false},{x:1992,y:300,got:false},{x:3162,y:347,got:false},{x:4362,y:286,got:false},{x:5543,y:319,got:false},{x:6707,y:350,got:false},{x:7882,y:294,got:false},{x:9062,y:337,got:false},{x:10242,y:322,got:false},{x:11433,y:305,got:false}],
    cam:0, lastSafe:{x:160,y:400}, done:false, wind:0, endX:12105
  };
  p.x=160; p.y=400; p.vx=0; p.vy=0; p.onGround=true; p.coyote=0; p.pose="idle"; p.phase=0; p.face=1; p.expr="glad"; p.landT=0; p.squashT=0;
}

function cloudPlatY(pl, t){
  if(!pl.move) return pl.y;
  return pl.y + Math.sin(t*1.1)*pl.move;
}

function updClouds(){
  layoutBG("himmel");
  const p=lead();
  const id=hitId();
  if(handleHud(id)) return;
  if(id==="btn-hopp" || id==="play") hopBuf=0.12;

  const ACC=620, MAX=120, GRAV=1150, JUMP=-520, CUT=-420;
  if(p.x < G.endX-40){
    p.vx += ACC*DT;
    if(p.vx>MAX) p.vx=MAX;
  } else {
    p.vx *= Math.pow(0.02, DT);
  }
  p.vy += GRAV*DT;
  if(p.onGround) p.coyote=0.13; else p.coyote=Math.max(0, p.coyote-DT);
  hopBuf=Math.max(0, hopBuf-DT);
  if(hopBuf>0 && p.coyote>0){
    p.vy=JUMP; p.onGround=false; p.coyote=0; hopBuf=0; p.pose="jump"; p.expr="skratt";
    sfx("jump");
  }
  if(!hopHeld && p.vy<CUT) p.vy=CUT;

  p.x += p.vx*DT;
  p.y += p.vy*DT;

  p.onGround=false;
  G.plats.forEach(pl=>{
    const py=cloudPlatY(pl,T);
    const withinX=p.x>pl.x-16 && p.x<pl.x+pl.w+16;
    const prevY=p.y - p.vy*DT;
    const wasAbove=prevY <= py+12;
    if(withinX && wasAbove && p.y>=py-22 && p.y<=py+28 && p.vy>=-20){
      p.y=py; p.vy=0; p.onGround=true;
      if(p.pose==="jump" || p.landT<=0){ p.landT=0.12; p.pose="land"; sfx("land"); }
      G.lastSafe={x:p.x, y:py};
      if(pl.typ==="goal" && !G.done){ G.done=true; G.winIn=0.55; sfx("cheer"); confetti(W/2, H/3, 30); }
    }
  });
  if(p.onGround){
    if(p.landT>0){ p.landT-=DT; p.pose="land"; }
    else { p.pose="walk"; p.expr="glad";
      const stridePx=56;
      p.phase=(p.phase||0)+Math.abs(p.vx)*DT/stridePx;
      if(p.phase>1) p.phase-=1;
      if(!p._lastC) p._lastC=0;
      if((p._lastC<0.5 && p.phase>=0.5)||(p._lastC>0.8 && p.phase<0.2)){ if(T>stepGate){ sfx("step"); stepGate=T+0.14; } }
      p._lastC=p.phase;
    }
  } else {
    p.pose="jump";
  }
  if(p.y>490){
    G.wind=0.7; p.x=G.lastSafe.x+12; p.y=G.lastSafe.y-4; p.vy=-30; p.vx=Math.max(60,p.vx*0.5);
    sfx("whoosh"); p.expr="forvanad";
  }
  if(G.wind>0) G.wind-=DT;
  G.stars.forEach(st=>{
    if(!st.got && Math.hypot(p.x-st.x, p.y-40-st.y)<46){
      st.got=true; sfx("star"); burst(0,0,12,"#ffe27a");
    }
  });
  G.scale = Math.min(W/520, H/400);
  const dest=p.x - (W/G.scale)*0.32;
  G.cam=lerp(G.cam||0, Math.max(0, dest), 0.1);
}

function drawCloudPlat(x,y,w,h,typ){
  ctx.save();
  ctx.translate(x+w/2, y);
  const hh=Math.max(28,h);
  if(typ==="ground"){
    ctx.fillStyle="#7cba72";
    ctx.strokeStyle="#3d6a3a";
    ctx.lineWidth=3.5;
    ctx.beginPath();
    ctx.moveTo(-w/2, 8);
    ctx.quadraticCurveTo(-w*0.25, -hh*1.1, 0, -hh*0.85);
    ctx.quadraticCurveTo(w*0.25, -hh*1.1, w/2, 8);
    ctx.quadraticCurveTo(0, 28, -w/2, 8);
    ctx.closePath(); ctx.fill(); ctx.stroke();
  } else {
    ctx.fillStyle= typ==="goal" ? "#fff4c8" : "#fff8ee";
    ctx.strokeStyle= typ==="goal" ? "#c9a24a" : "#5a3e3a";
    ctx.lineWidth=3.5;
    ctx.beginPath();
    ctx.moveTo(-w/2+10, 0);
    ctx.quadraticCurveTo(-w/2, -hh*0.7, -w/4, -hh*0.55);
    ctx.quadraticCurveTo(0, -hh*1.05, w/4, -hh*0.55);
    ctx.quadraticCurveTo(w/2, -hh*0.7, w/2-10, 0);
    ctx.lineTo(w/2-8, hh*0.45);
    ctx.quadraticCurveTo(0, hh*0.7, -w/2+8, hh*0.45);
    ctx.closePath();
    ctx.fill(); ctx.stroke();
    if(typ==="goal") blit("star", 0, -hh*0.15, {h:28});
  }
  ctx.restore();
}

function drawClouds(){
  drawSkyParallax(G.cam, G.endX);
  const sc=G.scale||Math.min(W/520, H/400);
  ctx.save();
  ctx.scale(sc, sc);
  const groundScreen=(H - Math.max(120, 0.16*H))/sc;
  ctx.translate(-G.cam, groundScreen-400);
  G.plats.forEach(pl=>{
    const py=cloudPlatY(pl,T);
    if(pl.x+pl.w<G.cam-80 || pl.x>G.cam+W/sc+80) return;
    drawCloudPlat(pl.x, py, pl.w, pl.h||34, pl.typ);
  });
  G.stars.forEach(st=>{
    if(st.got) return;
    if(st.x<G.cam-40 || st.x>G.cam+W/sc+40) return;
    blit("star", st.x, st.y+Math.sin(T*3+st.x)*4, {h:32, anchor:""});
  });
  const p=lead();
  let sy=1, sx=1;
  if(p.pose==="jump"){ sy=1.14; sx=0.86; }
  if(p.pose==="land"){ sy=0.82; sx=1.16; }
  drawHero(p.x, p.y, {who:p.id, expr:p.expr, scale:1.35, face:1, pose:p.pose, phase:p.phase, sx, sy});
  if(G.wind>0){
    ctx.fillStyle="rgba(180,220,255,0.35)";
    for(let i=0;i<6;i++){ ctx.beginPath(); ctx.ellipse(p.x-20-i*10, p.y-20+i*6, 18, 5, -0.2,0,TAU); ctx.fill(); }
  }
  ctx.restore();

  const L=lay();
  addHit("play", 0, H*0.18, Math.max(0, W-L.pad-100), H*0.82);
  const b=Math.max(84, 72*L.s);
  const bx=W-L.pad-b, by=H-L.pad-b;
  ctx.fillStyle=hopHeld?"#ffe27a":"rgba(255,247,230,0.95)";
  disk(bx+b/2, by+b/2, b/2); ctx.fill();
  ctx.strokeStyle="#e8c56b"; ctx.lineWidth=4; ctx.stroke();
  ctx.fillStyle="#5a3e3a";
  ctx.beginPath();
  ctx.moveTo(bx+b/2, by+18);
  ctx.lineTo(bx+b/2+18, by+b/2+4);
  ctx.lineTo(bx+b/2-18, by+b/2+4);
  ctx.closePath(); ctx.fill();
  addHit("btn-hopp", bx, by, b, b);
  const got=G.stars.filter(s=>s.got).length;
  for(let i=0;i<G.stars.length;i++){
    if(i<got) blit("star", L.pad+70+i*22, L.pad+36, {h:16});
    else { ctx.globalAlpha=0.35; blit("star", L.pad+70+i*22, L.pad+36, {h:16}); ctx.globalAlpha=1; }
  }
  drawHud(true);
}



/* ======== VÄRLD 4: Skattjakt ======== */
function initTreasure(){
  layoutBG("borggard");
  const p=lead(); p.x=0.20; p.y=0.94; p.vx=0; p.pose="idle"; p.expr="glad"; p.goal=null; p.phase=0; p.carry=null;
  G = {
    hides: [
      {id:"valv", key:"circle", x:0.445, y:0.36, found:false},
      {id:"bush", key:"tri",    x:0.825, y:0.62, found:false},
      {id:"pot",  key:"star",   x:0.14,  y:0.70, found:false}
    ],
    keys: [
      {id:"circle", x:0.445, y:0.42, hid:true, used:false},
      {id:"tri",    x:0.825, y:0.68, hid:true, used:false},
      {id:"star",   x:0.14,  y:0.76, hid:true, used:false}
    ],
    chests: [
      {id:"circle", spr:"chest-circle", x:0.34, y:0.84, open:false},
      {id:"tri",    spr:"chest-tri",    x:0.50, y:0.84, open:false},
      {id:"star",   spr:"chest-star",   x:0.66, y:0.84, open:false}
    ],
    holding:null
  };
}

function updTreasure(){
  layoutBG("borggard");
  const p=lead();
  const id=hitId();
  if(handleHud(id)) return;
  if(id==="valv"||id==="bush"||id==="pot"){
    const h=G.hides.find(h=>h.id===id);
    if(h && !h.found){
      h.found=true;
      const k=G.keys.find(k=>k.id===h.key);
      if(k) k.hid=false;
      sfx("open"); burst(worldToX(h.x), worldToY(h.y), 10, "#ffe27a");
    }
  }
  if(id && id.startsWith("key-")){
    const k=G.keys.find(k=>k.id===id.slice(4));
    if(k && !k.hid && !k.used && !G.holding){
      G.holding=k.id; p.carry=k.id; p.expr="modig"; p.pose="carry";
      sfx("ok");
    }
  }
  if(id && id.startsWith("chest-")){
    const c=G.chests.find(c=>c.id===id.slice(6));
    if(c && !c.open){
      if(G.holding===c.id){
        c.open=true;
        const k=G.keys.find(k=>k.id===c.id);
        if(k) k.used=true;
        G.holding=null; p.carry=null; p.expr="skratt"; p.pose="cheer";
        sfx("open"); confetti(worldToX(c.x), worldToY(c.y)-30, 16);
        if(G.chests.every(c=>c.open) && !G.done){ G.done=true; G.winIn=0.8; }
      } else {
        sfx("softno"); c._shake=0.4; p.expr="fundersam";
      }
    }
  }
  if(id==="bg" && tap){ const w=screenToWorld(tap.x,tap.y); p.goal={x:clamp(w.x,0.1,0.9), y:clamp(w.y,0.72,0.95)}; }
  if(p.goal) walkToward(p, worldToX(p.goal.x), worldToY(p.goal.y));
  G.chests.forEach(c=>{ if(c._shake) c._shake=Math.max(0,c._shake-DT); });
}

function drawTreasure(){
  drawBG("borggard", bgCourt);
  const L=lay();
  const p=lead();
  G.hides.forEach(h=>{
    const x=worldToX(h.x), y=worldToY(h.y);
    if(!h.found){
      addHit(h.id, x-36, y-36, 72, 72);
      if(idle>2.2) sparkle(x, y-10);
    }
  });
  G.keys.forEach(k=>{
    if(k.hid || k.used || G.holding===k.id) return;
    const x=worldToX(k.x), y=worldToY(k.y);
    blit("key", x, y, {h:44});
    addHit("key-"+k.id, x-32, y-44, 64, 72);
  });
  G.chests.forEach(c=>{
    const x=worldToX(c.x), y=worldToY(c.y);
    const shake=c._shake?Math.sin(T*22)*4:0;
    blit(c.open?"chest-open":c.spr, x+shake, y, {h:72});
    if(!c.open && c.id==="tri"){
      ctx.fillStyle="#c9a24a";
      ctx.strokeStyle="#5a3e3a"; ctx.lineWidth=2;
      ctx.beginPath();
      ctx.moveTo(x+shake, y-74);
      ctx.lineTo(x+shake-11, y-54);
      ctx.lineTo(x+shake+11, y-54);
      ctx.closePath(); ctx.fill(); ctx.stroke();
    }
    if(!c.open) addHit("chest-"+c.id, x-40, y-80, 80, 90);
  });
  drawHero(worldToX(p.x), worldToY(p.y), {who:p.id, expr:p.expr, scale:L.s, face:p.face||1, pose:p.pose, phase:p.phase});
  if(G.holding) blit("key", worldToX(p.x)+(p.face||1)*22, worldToY(p.y)-78, {h:36});
  if(idle>4){
    const nextHide=G.hides.find(h=>!h.found);
    const heldKey=G.holding && G.chests.find(c=>c.id===G.holding && !c.open);
    const loose=G.keys.find(k=>!k.hid && !k.used && G.holding!==k.id);
    if(heldKey) sparkle(worldToX(heldKey.x), worldToY(heldKey.y)-40);
    else if(loose) sparkle(worldToX(loose.x), worldToY(loose.y));
    else if(nextHide) sparkle(worldToX(nextHide.x), worldToY(nextHide.y));
  }
  drawHud(true);
}


/* ======== VÄRLD 5: Lilla bagaren ======== */
const ORDERS = [
  { who:"mouse", want:[{col:"red", n:1}] },
  { who:"bunny", want:[{col:"blue", n:2}] },
  { who:"bird",  want:[{col:"yellow", n:1},{col:"red", n:1}] },
  { who:"bear",  want:[{col:"red", n:5}] }
];
const POTS = [
  {id:"red", col:"#f37a62", topping:"berry"},
  {id:"blue", col:"#7ec8f0", topping:"berry"},
  {id:"yellow", col:"#ffe27a", topping:"star"}
];
function bakeryOk(){
  const g=G.guests.find(g=>!g.got);
  if(!g || !G.cake.base || !G.cake.layers.length) return false;
  const topLayer=G.cake.layers[G.cake.layers.length-1];
  return (g.want==="pink" && (topLayer==="pink" || G.cake.top==="berry"))
      || (g.want==="blue" && topLayer==="blue")
      || (g.want==="yellow" && (topLayer==="yellow" || G.cake.top==="star"));
}

function initBakery(){
  layoutBG("bageri");
  const p=lead(); p.x=0.36; p.y=0.96; p.vx=0; p.pose="idle"; p.expr="glad"; p.goal=null; p.phase=0; p.carry=null;
  G = {
    guests: [
      {id:"butterfly", kind:"butterfly", x:0.12, y:0.62, want:"pink",  got:false},
      {id:"ladybug",   kind:"ladybug",   x:0.90, y:0.62, want:"blue",  got:false},
      {id:"bird",      kind:"bird",      x:0.10, y:0.84, want:"yellow",got:false},
      {id:"bear",      kind:"bear",      x:0.84, y:0.80, want:"pink",  got:false}
    ],
    tray: {x:0.50, y:0.48},
    cake: {base:false, layers:[], top:null},
    held:null, ovenHot:false, done:false
  };
}


function updBakery(){
  layoutBG("bageri");
  const p=lead();
  const id=hitId();
  if(handleHud(id)) return;
  if(id==="oven"){
    G.ovenHot=true; sfx("pop");
    if(!G.cake.base && !G.held){ G.held="base"; p.carry="base"; p.pose="carry"; sfx("ok"); }
  }
  if(id==="base" && G.ovenHot && !G.cake.base && !G.held){
    G.held="base"; p.carry="base"; p.pose="carry"; sfx("ok");
  }
  if(id && id.startsWith("ing-") && G.held && G.held===id.slice(4)){
    G.held=null; p.carry=null; p.pose="idle";
  }
  if(id==="tray"){
    if(G.held==="base" && !G.cake.base){
      G.cake.base=true; G.held=null; p.carry=null; sfx("plant");
    } else if(G.held && G.held!=="base" && G.cake.base){
      if(G.held==="berry" || G.held==="star") G.cake.top=G.held;
      else G.cake.layers.push(G.held);
      G.held=null; p.carry=null; sfx("pop");
    }
  }
  if(id && id.startsWith("ing-")){
    const k=id.slice(4);
    if(!G.held){ G.held=k; p.carry=k; p.pose="carry"; sfx("tap"); }
  }
  if(id && id.startsWith("guest-")){
    const g=G.guests.find(g=>g.id===id.slice(6));
    if(g && !g.got && bakeryOk() && (g.want===G.cake.layers[G.cake.layers.length-1] || (g.want==="pink"&&G.cake.top==="berry") || (g.want==="yellow"&&G.cake.top==="star"))){
      g.got=true; sfx("heart"); confetti(worldToX(g.x), worldToY(g.y)-20, 12);
      G.cake={base:false, layers:[], top:null}; G.ovenHot=false; G.held=null; p.carry=null;
      if(G.guests.every(g=>g.got) && !G.done){ G.done=true; G.winIn=0.8; }
    } else if(g && !g.got){
      sfx("softno"); g._shake=0.4; p.expr="fundersam";
    }
  }
  if(id==="bg" && tap){ const w=screenToWorld(tap.x,tap.y); p.goal={x:clamp(w.x,0.08,0.92), y:clamp(w.y,0.78,0.96)}; }
  if(p.goal) walkToward(p, worldToX(p.goal.x), worldToY(p.goal.y));
  G.guests.forEach(g=>{ if(g._shake) g._shake=Math.max(0,g._shake-DT); });
}

function drawBakery(){
  drawBG("bageri", bgBakery);
  const L=lay();
  const p=lead();
  const tx=worldToX(G.tray.x), ty=worldToY(G.tray.y);
  if(G.cake.base){
    ctx.fillStyle="#9eb8b4";
    oval(tx, ty-28, 50, 54); ctx.fill();
    ctx.fillStyle="#f3efe2";
    oval(tx, ty+2, 48, 12); ctx.fill();
    ctx.strokeStyle="#d8c4a0"; ctx.lineWidth=2;
    oval(tx, ty+2, 48, 12); ctx.stroke();

    blit("cake-base", tx, ty, {h:36});
    G.cake.layers.forEach((ly,i)=>{
      blit("cake-"+ly, tx, ty-18-i*16, {h:32});
    });
    if(G.cake.top==="berry") blit("berry", tx, ty-18-G.cake.layers.length*16-8, {h:22});
    if(G.cake.top==="star") blit("star", tx, ty-18-G.cake.layers.length*16-8, {h:22});
  }
  const ox=worldToX(0.86), oy=worldToY(0.42);
  if(G.ovenHot){ ctx.globalAlpha=0.35; ctx.fillStyle="#ff9a40"; disk(ox,oy,40); ctx.fill(); ctx.globalAlpha=1; }
  if(!G.cake.base){
    const bx=worldToX(0.72), by=worldToY(0.58);
    if(G.ovenHot) blit("cake-base", bx, by, {h:32});
  }
  const ings=[{id:"pink",x:0.28,y:0.94},{id:"blue",x:0.42,y:0.94},{id:"yellow",x:0.56,y:0.94},{id:"berry",x:0.70,y:0.94},{id:"star",x:0.84,y:0.94}];
  ings.forEach(ing=>{
    const x=worldToX(ing.x), y=worldToY(ing.y);
    const sel=G.held===ing.id;
    if(sel){ ctx.fillStyle="rgba(255,226,122,0.5)"; disk(x,y-8,26); ctx.fill(); }
    const spr = ing.id==="berry"||ing.id==="star"?ing.id:"cake-"+ing.id;
    blit(spr, x, y, {h:32});
  });
  G.guests.forEach(g=>{
    const x=worldToX(g.x), y=worldToY(g.y);
    const shake=g._shake?Math.sin(T*20)*3:0;
    drawAnimal(g.kind, x+shake, y, L.s, g.got?"skratt":"glad", g.x<0.5?1:-1);
    if(!g.got){
      const bub=hintBubble(x, y, g.kind, L.s, "cake-"+g.want);
      const hx=Math.min(x-32,bub.x-4), hy=Math.min(y-figureH(g.kind,L.s)-8,bub.y-4);
      addHit("guest-"+g.id, hx, hy, Math.max(x+32,bub.x+bub.w+4)-hx, Math.max(y+8,bub.y+bub.h+4)-hy);
    } else {
      drawHeart(x, y-figureH(g.kind,L.s)-6);
    }
  });
  addHit("tray", tx-50, ty-80, 100, 100);
  addHit("oven", ox-40, oy-40, 80, 80);
  if(!G.cake.base){
    const bx=worldToX(0.72), by=worldToY(0.58);
    addHit("base", bx-32, by-36, 64, 64);
  }
  ings.forEach(ing=>{
    const x=worldToX(ing.x), y=worldToY(ing.y);
    addHit("ing-"+ing.id, x-32, y-40, 64, 64);
  });
  drawHero(worldToX(p.x), worldToY(p.y), {who:p.id, expr:p.expr, scale:L.s, face:p.face||1, pose:p.pose, phase:p.phase});
  if(G.held){
    const spr=G.held==="base"?"cake-base":(G.held==="berry"||G.held==="star"?G.held:"cake-"+G.held);
    blit(spr, worldToX(p.x)+(p.face||1)*20, worldToY(p.y)-76, {h:28});
  }
  if(idle>3.5){
    if(!G.ovenHot && !G.cake.base) sparkle(ox, oy);
    else if(G.ovenHot && !G.cake.base && !G.held) sparkle(worldToX(0.72), worldToY(0.58));
    else if(G.held==="base") sparkle(tx, ty);
    else if(G.cake.base && G.cake.layers.length===0 && !G.held) sparkle(worldToX(0.42), worldToY(0.94));
    else {
      const g=G.guests.find(g=>!g.got);
      if(g && G.cake.layers.length) sparkle(worldToX(g.x), worldToY(g.y)-40);
    }
  }
  drawHud(true);
}


/* ---- huvudloop och scenväxling ---- */
function go(name){
  const forra=scene;
  if(name!==forra && !(typeof reduceradRorelse==="function" && reduceradRorelse())){
    try { fade({ farg: "rgba(244,230,196,0.92)", ms: 150 }); } catch(e) {}
  }
  scene=name; sceneT=0; idle=0; tap=null; hopBuf=0;
  parts.length=0;
  const w = WORLDS.find(w=>w.id===name);
  setTheme(w?w.theme: (name==="title"||name==="pick"?"title": name==="celebrate"?"party": name==="stickers"||name==="kod"?"map":"map"));
  if(name==="pick") G={};
  if(name==="kod") initKod();
  if(name==="rescue") initRescue();
  else if(name==="garden") initGarden();
  else if(name==="clouds") initClouds();
  else if(name==="treasure") initTreasure();
  else if(name==="bakery") initBakery();
  if(name==="pick") tala("valj");
  else if(name==="map" && (forra==="pick" || forra==="title")){
    if(!persist.heardTrad){ persist.heardTrad=true; saveNow(); tala("trad"); }
    else tala("karta");
  }
  else if(name==="stickers") tala("stickers");
  else if(name==="rescue"||name==="garden"||name==="clouds"||name==="treasure"||name==="bakery") tala(name);
  else if(name==="slut") tala("slut");
  else if(name==="foralder") tala("oversikt");

}

let fpsM=null;
function startFps(){ fpsM={ n:0, t0:0, min:999, last:0 }; }
function stopFps(){
  if(!fpsM||!fpsM.n) return null;
  const dt=Math.max(0.001,(fpsM.last-fpsM.t0)/1000);
  const r={ fps:fpsM.n/dt, minFps:fpsM.min, frames:fpsM.n, ms:dt*1000 };
  fpsM=null; return r;
}
function tick(now){
  if(!last) last=now;
  if(fpsM){
    if(!fpsM.t0) fpsM.t0=now;
    if(fpsM.last){ const inst=1000/Math.max(0.001,now-fpsM.last); if(inst<fpsM.min) fpsM.min=inst; }
    fpsM.last=now; fpsM.n++;
  }

  DT=clamp((now-last)/1000, 0, 0.05);
  last=now; T+=DT; sceneT+=DT; idle+=DT;
  musicTick();
  const p=lead();
  if(!p.id && persist.hero) p.id=persist.hero;

  if(scene==="title") updTitle();
  else if(scene==="pick") updPick();
  else if(scene==="map") updMap();
  else if(scene==="stickers") updStickers();
  else if(scene==="celebrate") updCelebrate();
  else if(scene==="kod") updKod();
  else if(scene==="slut") updSlut();
  else if(scene==="foralder") updForalder();
  else if(scene==="rescue") updRescue();
  else if(scene==="garden") updGarden();
  else if(scene==="clouds") updClouds();
  else if(scene==="treasure") updTreasure();
  else if(scene==="bakery") updBakery();

  if(G && G.winIn!=null){ G.winIn-=DT; if(G.winIn<=0){ const id=scene; G.winIn=null; startCelebrate(id); } }

  updParts(DT);
  targets.length=0;

  if(scene==="title") drawTitle();
  else if(scene==="pick") drawPick();
  else if(scene==="map") drawMap();
  else if(scene==="stickers") drawStickers();
  else if(scene==="celebrate") drawCelebrate();
  else if(scene==="kod") drawKod();
  else if(scene==="slut") drawSlut();
  else if(scene==="foralder") drawForalder();
  else if(scene==="rescue") drawRescue();
  else if(scene==="garden") drawGarden();
  else if(scene==="clouds") drawClouds();
  else if(scene==="treasure") drawTreasure();
  else if(scene==="bakery") drawBakery();
  drawParts();

  tap=null;
  requestAnimationFrame(tick);
}

/* ---- test-API ---- */
window.__ak = {
  SPARKOD: SPARKOD,
  get scene(){ return scene; },
  get hero(){ return (lead().id||persist.hero); },
  get stickers(){ return Object.assign({}, persist.stickers); },
  get gardenVisit(){ return persist.gardenVisit; },
  targets(){ return targets.map(t=>({id:t.id,x:t.x,y:t.y,w:t.w,h:t.h,cx:t.cx,cy:t.cy})); },
  target(id){ return this.targets().find(t=>t.id===id)||null; },
  state(){ return { scene, t:sceneT, hero:this.hero, stickers:this.stickers, G: summarizeG() }; },
  loadSprites(){ loadSlots(); },
  setSprite(who, dataUrl){ if(SPRITE_DATA.hasOwnProperty(who)){ SPRITE_DATA[who]=dataUrl; SLOT[who]._tried=false; loadSlots(); } },
  go: go,
  /* Party är redo för en andra medlem senare: Party.members.push({id:"norin",...}) */
  tala,
  fira: startCelebrate,
  startFps, stopFps,
  minnen: () => minnenAntal(),

  gladjedans,
  Party,
  ljud,
  spar
};
window.ReferensSpel = window.__ak;

function summarizeG(){
  if(scene==="rescue") return { home: (G.animals||[]).map(a=>({id:a.id,home:a.home,hid:!!a.baby.hid,carry:lead().carry})) };
  if(scene==="garden") return { plots:(G.plots||[]).map(p=>({i:p.i,seed:p.seed,stage:p.stage})), tool:G.tool, done:G.done, visit:G.visit };
  if(scene==="clouds") return { x:lead().x, y:lead().y, onGround:lead().onGround, stars:(G.stars||[]).filter(s=>s.got).length, done:G.done };
  if(scene==="treasure") return { holding:G.holding, open:(G.chests||[]).map(c=>({id:c.id,open:c.open})), keys:(G.keys||[]).map(k=>({id:k.id,hid:k.hid,used:k.used})) };
  if(scene==="bakery") return { held:G.held, cake:G.cake&&{base:G.cake.base,layers:G.cake.layers.slice(),top:G.cake.top}, guests:(G.guests||[]).map(g=>({id:g.id,got:g.got,want:g.want})), ovenHot:!!G.ovenHot, ok:(typeof bakeryOk==="function")&&bakeryOk(), done:G.done };
  if(scene==="celebrate") return { world: celebrate&&celebrate.world, t:celebrate&&celebrate.t };
  if(scene==="slut"||scene==="foralder") return { ended:!!persist.ended, minnen:minnenAntal() };
  return { keys: Object.keys(G||{}) };
}



function bindChrome(){
  const spara = document.getElementById("knapp-spara");
  const forts = document.getElementById("knapp-fortsatt");
  const nytt = document.getElementById("knapp-nytt");
  const hel = document.getElementById("knapp-helskarm");
  const ov = document.getElementById("knapp-oversikt");
  const vMusik = document.getElementById("vol-musik");
  const vSfx = document.getElementById("vol-sfx");
  const vAllt = document.getElementById("vol-allt");
  if(spara) spara.addEventListener("click", async () => {
    await unlockAudio();
    await spar.sparaManuellt();
    uppdateraSparStatus();
  });
  if(forts) forts.addEventListener("click", async () => {
    await unlockAudio();
    const data = await spar.load();
    if(data){
      applySave(data);
      if(persist.hero) go("map");
      else go("pick");
    }
  });
  if(nytt) nytt.addEventListener("click", async () => {
    await unlockAudio();
    const res = await spar.nytt({ bekrafta: monteraBekraftelse({
      titel: "Börja om?",
      text: "Det raderar klistermärken och valt barn.",
      okEtikett: "Nytt",
      avbrytEtikett: "Avbryt"
    }) });
    if(res && res.avbrott) return;
    persist = tomPersist();
    setMuted(false);
    go("title");
    uppdateraSparStatus();
  });
  if(ov) ov.addEventListener("click", async () => {
    await unlockAudio();
    go("foralder");
  });
  if(hel) hel.addEventListener("click", async () => {
    try {
      if(!document.fullscreenElement) await document.documentElement.requestFullscreen();
      else await document.exitFullscreen();
    } catch(e) {}
  });
  if(vMusik){
    vMusik.value = ljud.getVolume("music");
    vMusik.addEventListener("input", () => ljud.setVolume("music", vMusik.value));
  }
  if(vSfx){
    vSfx.value = ljud.getVolume("Ljud");
    vSfx.addEventListener("input", () => ljud.setVolume("Ljud", vSfx.value));
  }
  if(vAllt){
    vAllt.value = ljud.getVolume("master");
    vAllt.addEventListener("input", () => ljud.setVolume("master", vAllt.value));
  }
}

async function boot(){
  const q = new URLSearchParams(location.search);
  if(q.get("studiointro")==="0") window.__SKIP_STUDIOINTRO = true;
  await loadSave();
  loadBackgrounds();
  loadAtlas();
  loadSlots();
  resize();
  bindChrome();
  ljud.attachUnlock(document);
  if(window.StudioIntro && !window.__SKIP_STUDIOINTRO){
    StudioIntro.play({
      brand:"spel",
      partners:[],
      copyright:"© 2026 SkaparKvarnen (Skaparkvarnen, enskild firma). Alla rättigheter förbehållna.",
      onDone:function(){ requestAnimationFrame(tick); }
    });
  } else {
    requestAnimationFrame(tick);
  }
}
boot();
